package com.fiscuvia;

import java.util.*;
import java.sql.*;
import java.util.concurrent.*;
import java.util.function.Consumer;
import org.junit.jupiter.api.*;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.annotation.DirtiesContext;
import org.springframework.test.context.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.SingleConnectionDataSource;
import org.testcontainers.junit.jupiter.*;
import static org.assertj.core.api.Assertions.*;

/** Real OIDC + PostgreSQL, with policy/hook fixtures explicitly isolated pending approval. */
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.DEFINED_PORT)
@ActiveProfiles("test") @Testcontainers @DirtiesContext(classMode=DirtiesContext.ClassMode.AFTER_CLASS)
@Timeout(60)
class EntitlementTests {
 static final LocalTls TLS=new LocalTls();
 @Container static final PostgresTestDatabase DATABASE=new PostgresTestDatabase();
 @Container static final KeycloakTestProvider OIDC=new KeycloakTestProvider(TLS.origin());
 @DynamicPropertySource static void properties(DynamicPropertyRegistry r){DATABASE.register(r);TLS.register(r);r.add("fiscuvia.identity.enabled",()->true);r.add("fiscuvia.identity.issuer",OIDC::issuer);r.add("fiscuvia.identity.client-secret",()->OIDC.clientSecret);r.add("fiscuvia.identity.mfa-policy",()->"keycloak-local-otp-v1");}
 @org.springframework.beans.factory.annotation.Autowired com.fiscuvia.identity.AuthorizedTenantOperations operations;
 static OidcBrowser owner,other;static UUID ownerId,otherId;
 @BeforeEach void identities() throws Exception {if(owner!=null)return;owner=new OidcBrowser(TLS,OIDC);other=new OidcBrowser(TLS,OIDC);ownerId=UUID.fromString(owner.login("alice").path("userId").asText());otherId=UUID.fromString(other.login("bob").path("userId").asText());}
 @AfterAll static void close(){if(owner!=null)owner.close();if(other!=null)other.close();}
 Connection migration() throws Exception{return DriverManager.getConnection(DATABASE.getJdbcUrl(),PostgresTestDatabase.MIGRATION_USER,DATABASE.migrationPassword);}
 void admin(UUID tenant,Consumer<JdbcTemplate> work) throws Exception {try(var c=migration()){c.setAutoCommit(false);var s=new JdbcTemplate(new SingleConnectionDataSource(c,true));if(tenant!=null)s.queryForObject("SELECT app.establish_tenant_context(?)",Object.class,tenant);work.accept(s);c.commit();}}
 UUID firm() throws Exception{UUID[] id={null};admin(null,s->id[0]=s.queryForObject("SELECT tenant_private.provision(?,?,?,'DEMO cuotas',NULL,NULL,'America/Mexico_City','es-MX')",UUID.class,UUID.randomUUID(),ownerId,UUID.randomUUID()));return id[0];}
 long assign(UUID t,UUID key,long version,long limit) throws Exception{long[] v={0};admin(null,s->v[0]=s.queryForObject("SELECT entitlement_private.assign_limit(?,?,?,'USERS',?,?,NULL)",Long.class,t,key,key,limit,version));return v[0];}
 String path(UUID t){return "/api/v1/tenants/"+t+"/entitlements";}
 void viewPolicy(boolean enabled) throws Exception{admin(null,s->{s.update("DELETE FROM access_control_private.role_capabilities WHERE capability='TENANT_PLAN_VIEW'");if(enabled)s.update("INSERT INTO access_control_private.role_capabilities VALUES('FIRM_OWNER_ADMIN','TENANT_PLAN_VIEW','TENANT',true,'SYNTHETIC TEST ONLY #32')");});}
 void hook(boolean enabled) throws Exception{admin(null,s->{s.execute("DROP TRIGGER IF EXISTS entitlement_capacity ON identity.memberships");if(enabled)s.execute("CREATE TRIGGER entitlement_capacity BEFORE INSERT OR UPDATE ON identity.memberships FOR EACH ROW EXECUTE FUNCTION entitlement_private.membership_capacity()");});}
 void addMember(UUID t,UUID user,String state) throws Exception{admin(t,s->s.update("INSERT INTO identity.memberships VALUES(?,?,?, ?,clock_timestamp(),clock_timestamp())",t,UUID.randomUUID(),user,state));}
 long count(UUID t,String table) throws Exception{long[] n={0};admin(t,s->n[0]=s.queryForObject("SELECT count(*) FROM "+table,Long.class));return n[0];}
 @Test void queryDeniesWithoutPolicyEvenForOwnerAndHasNoEditEndpoint() throws Exception {UUID t=firm();viewPolicy(false);assertThat(owner.get(path(t)).statusCode()).isEqualTo(403);assertThat(owner.send("POST",path(t),"{}",owner.csrf()).statusCode()).isIn(403,405);}
 @Test void authorizedUsageCountsRealMembershipAndFutureResourcesRemainUnmeasured() throws Exception{UUID t=firm();assign(t,UUID.randomUUID(),0,3);viewPolicy(true);try{var r=owner.get(path(t));assertThat(r.statusCode()).isEqualTo(200);assertThat(r.headers().firstValue("Cache-Control")).hasValue("no-store");var rows=OidcBrowser.json(r);assertThat(rows.size()).isEqualTo(6);assertThat(rows.get(0).path("measured").asLong()).isEqualTo(1);assertThat(rows.get(0).path("available").asLong()).isEqualTo(2);for(int i=1;i<6;i++){assertThat(rows.get(i).path("measured").isNull()).isTrue();assertThat(rows.get(i).path("integration").asText()).isEqualTo("NOT_INTEGRATED");}}finally{viewPolicy(false);}}
 @Test void tenantIsolationAndForgedUuidAndAnonymous() throws Exception{UUID a=firm(),b=firm();assign(a,UUID.randomUUID(),0,2);assign(b,UUID.randomUUID(),0,8);viewPolicy(true);try{assertThat(other.get(path(a)).statusCode()).isEqualTo(403);assertThat(owner.get(path(UUID.randomUUID())).statusCode()).isEqualTo(403);try(var anon=new OidcBrowser(TLS,OIDC)){assertThat(anon.get(path(a)).statusCode()).isEqualTo(401);}}finally{viewPolicy(false);}}
 @Test void noConfigurationIsExplicitAndNeverUnlimited() throws Exception{UUID t=firm();viewPolicy(true);try{var r=OidcBrowser.json(owner.get(path(t))).get(0);assertThat(r.path("limit").isNull()).isTrue();assertThat(r.path("available").isNull()).isTrue();assertThat(r.path("measured").asLong()).isEqualTo(1);}finally{viewPolicy(false);}}
 @Test void administrationIsVersionedIdempotentAndAudited() throws Exception{UUID t=firm(),key=UUID.randomUUID();assertThat(assign(t,key,0,4)).isEqualTo(1);assertThat(assign(t,key,0,4)).isEqualTo(1);assertThatThrownBy(()->assign(t,key,0,5)).hasRootCauseInstanceOf(SQLException.class);assertThatThrownBy(()->assign(t,UUID.randomUUID(),0,8)).hasRootCauseInstanceOf(SQLException.class);assertThat(count(t,"journal.events")).isEqualTo(3);assertThat(count(t,"journal.outbox")).isEqualTo(3);admin(t,s->assertThat(s.queryForObject("SELECT count(*) FROM entitlement_private.changes WHERE tenant_id=?",Long.class,t)).isEqualTo(1));}
 @Test void reductionBelowUsageRetainsMembersAndReportsOverage() throws Exception{UUID t=firm();assign(t,UUID.randomUUID(),0,0);viewPolicy(true);try{assertThat(count(t,"identity.memberships")).isEqualTo(1);var r=OidcBrowser.json(owner.get(path(t))).get(0);assertThat(r.path("overLimit").asBoolean()).isTrue();assertThat(r.path("available").asLong()).isZero();}finally{viewPolicy(false);}}
 @Test void invalidNegativeAndOverflowLimitsAreRejected() throws Exception{UUID t=firm();for(long n:new long[]{-1,9007199254740992L,Long.MAX_VALUE})assertThatThrownBy(()->assign(t,UUID.randomUUID(),0,n)).hasRootCauseInstanceOf(SQLException.class);}
 @Test void runtimeCannotAccessPrivateTablesOrAdministrativeFunctions() throws Exception{try(var c=DriverManager.getConnection(DATABASE.getJdbcUrl(),PostgresTestDatabase.RUNTIME_USER,DATABASE.runtimePassword);var s=c.createStatement()){assertThatThrownBy(()->s.execute("SELECT * FROM entitlement_private.limits")).isInstanceOf(SQLException.class);assertThatThrownBy(()->s.execute("SELECT entitlement_private.assign_limit(NULL,NULL,NULL,'USERS',99,0,NULL)")).isInstanceOf(SQLException.class);assertThatThrownBy(()->s.execute("SELECT entitlement_api.usage(gen_random_uuid())")).isInstanceOf(SQLException.class);}}
 @Test void migratorStillHonorsTenantRlsAndAllTablesForceRls() throws Exception{UUID a=firm(),b=firm();assign(a,UUID.randomUUID(),0,2);assign(b,UUID.randomUUID(),0,7);admin(a,s->{assertThat(s.queryForObject("SELECT count(*) FROM entitlement_private.limits WHERE tenant_id=?",Integer.class,b)).isZero();assertThat(s.queryForObject("SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='entitlement_private' AND c.relkind='r' AND c.relrowsecurity AND c.relforcerowsecurity",Integer.class)).isEqualTo(3);});}
 @Test void proposedHookEnforcesExactLimitAndPreservesSuspendedAndRevoked() throws Exception{UUID t=firm();assign(t,UUID.randomUUID(),0,1);hook(true);try{assertThatThrownBy(()->addMember(t,otherId,"ACTIVE")).hasRootCauseInstanceOf(SQLException.class);addMember(t,otherId,"SUSPENDED");admin(t,s->assertThat(s.queryForObject("SELECT entitlement_private.measured_users(?)",Long.class,t)).isEqualTo(1));}finally{hook(false);}}
 @Test void proposedHookAllowsLastUnitAndRejectsOneMore() throws Exception{UUID t=firm();assign(t,UUID.randomUUID(),0,2);hook(true);try{addMember(t,otherId,"ACTIVE");assertThat(count(t,"identity.memberships")).isEqualTo(2);}finally{hook(false);}}
 @Test void disabledIdentityStillOccupiesActiveMembership() throws Exception{UUID t=firm();assign(t,UUID.randomUUID(),0,2);addMember(t,otherId,"ACTIVE");admin(null,s->s.update("UPDATE identity_private.users SET status='DISABLED' WHERE id=?",otherId));try{admin(t,s->assertThat(s.queryForObject("SELECT entitlement_private.measured_users(?)",Long.class,t)).isEqualTo(2));}finally{admin(null,s->s.update("UPDATE identity_private.users SET status='ACTIVE' WHERE id=?",otherId));}}
 @Test void failedJournalRollsBackQuotaAndReceipt() throws Exception{UUID t=firm();admin(null,s->s.execute("CREATE FUNCTION entitlement_private.test_fail() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'synthetic'; END $$; CREATE TRIGGER entitlement_test_fail BEFORE INSERT ON journal.outbox FOR EACH ROW EXECUTE FUNCTION entitlement_private.test_fail()"));try{assertThatThrownBy(()->assign(t,UUID.randomUUID(),0,3)).hasRootCauseInstanceOf(SQLException.class);}finally{admin(null,s->s.execute("DROP TRIGGER entitlement_test_fail ON journal.outbox; DROP FUNCTION entitlement_private.test_fail()"));}admin(t,s->assertThat(s.queryForObject("SELECT count(*) FROM entitlement_private.limits",Integer.class)).isZero());assertThat(count(t,"journal.events")).isEqualTo(2);}
 @Test void configurationRaceAcceptsExactlyOneExpectedVersion() throws Exception{UUID t=firm();var start=new CyclicBarrier(2);try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var work=(Callable<Boolean>)()->{start.await();try{assign(t,UUID.randomUUID(),0,3);return true;}catch(Exception conflict){return false;}};var a=pool.submit(work);var b=pool.submit(work);assertThat(List.of(a.get(),b.get())).containsExactlyInAnyOrder(true,false);}}

 void engine(UUID tenant,UUID command,Consumer<JdbcTemplate> work) throws Exception {admin(tenant,s->{
   s.update("INSERT INTO identity_private.actor_context VALUES(pg_current_xact_id(),?,extract(epoch FROM clock_timestamp())::bigint,?,true)",ownerId,tenant);
   UUID m=s.queryForObject("SELECT id FROM identity.memberships WHERE tenant_id=? AND user_id=?",UUID.class,tenant,ownerId);
   s.update("INSERT INTO access_control_private.operation_context VALUES(pg_current_xact_id(),?,?,?,'MEMBERSHIP_INVITE','TENANT',NULL,'{}')",ownerId,tenant,m);
   s.update("INSERT INTO journal_private.command_context VALUES(pg_current_xact_id(),?,gen_random_uuid())",command);work.accept(s);
 });}
 String reserve(UUID t,UUID key,UUID user) throws Exception {String[] result={null};engine(t,key,s->result[0]=s.queryForObject("SELECT entitlement_api.reserve_user(?,?,?)",String.class,t,key,user));return result[0];}
 @Test void reservationIsIdempotentAndCountsOnlyHeldCapacity() throws Exception {UUID t=firm(),key=UUID.randomUUID();assign(t,UUID.randomUUID(),0,2);assertThat(reserve(t,key,otherId)).isEqualTo("RESERVED");assertThat(reserve(t,key,otherId)).isEqualTo("RESERVED");assertThat(count(t,"entitlement_private.reservations")).isEqualTo(1);assertThat(count(t,"identity.memberships")).isEqualTo(1);assertThat(count(t,"journal.outbox")).isEqualTo(4);}
 @Test void releaseTwiceDoesNotCreateDuplicateAuditOrUsage() throws Exception{UUID t=firm(),key=UUID.randomUUID();assign(t,UUID.randomUUID(),0,2);reserve(t,key,otherId);for(int i=0;i<2;i++) {UUID release=UUID.randomUUID();engine(t,release,s->assertThat(s.queryForObject("SELECT entitlement_api.release_user(?,?,?)",String.class,t,key,release)).isEqualTo("RELEASED"));}assertThat(count(t,"journal.events")).isEqualTo(5);assertThat(count(t,"identity.memberships")).isEqualTo(1);}
 @Test void reservationRollsBackWithCallerFailure() throws Exception{UUID t=firm(),key=UUID.randomUUID();assign(t,UUID.randomUUID(),0,2);assertThatThrownBy(()->engine(t,key,s->{s.queryForObject("SELECT entitlement_api.reserve_user(?,?,?)",String.class,t,key,otherId);throw new IllegalStateException("synthetic");})).isInstanceOf(IllegalStateException.class);assertThat(count(t,"entitlement_private.reservations")).isZero();assertThat(reserve(t,key,otherId)).isEqualTo("RESERVED");}
 @Test void existingReservationDoesNotBypassReducedLimitOnConfirmation() throws Exception{UUID t=firm(),key=UUID.randomUUID();assign(t,UUID.randomUUID(),0,2);reserve(t,key,otherId);assign(t,UUID.randomUUID(),1,1);hook(true);try{assertThatThrownBy(()->addMember(t,otherId,"ACTIVE")).hasRootCauseInstanceOf(SQLException.class);assertThat(count(t,"identity.memberships")).isEqualTo(1);admin(t,s->assertThat(s.queryForObject("SELECT status FROM entitlement_private.reservations WHERE command_id=?",String.class,key)).isEqualTo("RESERVED"));}finally{hook(false);}}
 @Test void confirmationConsumesReservationOnlyAlongsideRealMembership() throws Exception{UUID t=firm(),key=UUID.randomUUID();assign(t,UUID.randomUUID(),0,2);reserve(t,key,otherId);hook(true);try{addMember(t,otherId,"ACTIVE");assertThat(count(t,"identity.memberships")).isEqualTo(2);assertThat(reserve(t,key,otherId)).isEqualTo("CONFIRMED");}finally{hook(false);}}
 @Test void twoConcurrentReservationsCannotConsumeLastUnit() throws Exception{UUID t=firm();assign(t,UUID.randomUUID(),0,2);UUID carol=UUID.randomUUID();admin(null,s->s.update("INSERT INTO identity_private.users(id) VALUES(?)",carol));var start=new CyclicBarrier(2);try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var a=pool.submit(()->{start.await();return reserve(t,UUID.randomUUID(),otherId);});var b=pool.submit(()->{start.await();return reserve(t,UUID.randomUUID(),carol);});assertThat(List.of(a.get(),b.get())).containsExactlyInAnyOrder("RESERVED","EXHAUSTED");}}
 @Test void zeroExactExcessAndAbsentConfigurationReservations() throws Exception{UUID t=firm();assertThat(reserve(t,UUID.randomUUID(),otherId)).isEqualTo("UNCONFIGURED");assign(t,UUID.randomUUID(),0,0);assertThat(reserve(t,UUID.randomUUID(),otherId)).isEqualTo("EXHAUSTED");assign(t,UUID.randomUUID(),1,1);assertThat(reserve(t,UUID.randomUUID(),otherId)).isEqualTo("EXHAUSTED");assign(t,UUID.randomUUID(),2,2);assertThat(reserve(t,UUID.randomUUID(),otherId)).isEqualTo("RESERVED");}
}
